import { strict as assert } from "node:assert";
import { test } from "node:test";
import { parseRange } from "./parse-range.mjs";

test("reads a span", () => {
  assert.deepEqual(parseRange("3-9"), { from: 3, to: 9 });
});

test("reads a single number as a span of one", () => {
  assert.deepEqual(parseRange("7"), { from: 7, to: 7 });
});

